import {
  toAgeCategory,
  toBmiCategory,
  toCountryCategory,
  toCesareanCategory,
  toDeliveriesCategory,
  toMaritalStatusCategory,
  toRhCategory,
  toRoleCategory,
  toRoleCategories,
} from './matchingDataProvider';
import { listPaymentBuckets } from './donorPrograms';
import { getProgramRates } from './programCurrency';
import { hasActiveSearchKeyFilterGroup } from './searchKeyBuckets';

/**
 * Скільки карток підпадає під кожну опцію групи — серед уже завантажених.
 *
 * Число біля опції — це не прикраса, а відповідь на питання «що буде, якщо я
 * це зніму». Поки його не було, звуження робилось наосліп: читач гасив «≤25» і
 * дивився, чи щось змінилось у списку.
 *
 * Рахують тут **ті самі** категоризатори, що й пост-фільтр та індексний план
 * (`matchingDataProvider`). Своєї копії межі тут заводити не можна: саме
 * розбіжність на окрузі («26_30» проти «26–30 включно») і робить число
 * неправдою — воно обіцяло б одне, а фільтр давав би інше.
 *
 * **Групи крові тут немає, і це не пропуск.** Картка стрічки носить лише знак
 * резуса: номер групи з проєкції прибрано, бо разом вони складаються назад у
 * повне `blood`, яке живе за межею приватності (`toBloodGroupCategory` на
 * такій картці чесно каже `unknown`). Звужує за групою індекс `searchKey/blood`
 * — ще до того, як картка сюди дійде. Тож числа для неї були б нулями в усіх
 * пʼятьох опціях, тобто рядом чіпів, який відмовляє сам собі.
 */
const CATEGORIZERS = {
  userRole: toRoleCategory,
  maritalStatus: toMaritalStatusCategory,
  rh: toRhCategory,
  age: toAgeCategory,
  bmi: toBmiCategory,
  country: toCountryCategory,
  deliveries: toDeliveriesCategory,
  cesarean: toCesareanCategory,
  payment: listPaymentBuckets,
};

export const matchingFilterGroupHasCounts = filterName => Boolean(CATEGORIZERS[filterName]);

/**
 * `{ [опція]: скільки }` для однієї групи, або `null`, якщо картка на це
 * питання не відповідає.
 *
 * Роль читається через `roleIndexSets` тим самим шляхом, що й фільтр: у картці
 * ролі може не бути зовсім, а в бакеті `searchKey/users/role` вона є.
 */
export const countMatchingFilterOptions = ({ filterName, users = [], roleIndexSets = null, programRates = getProgramRates() } = {}) => {
  const categorize = CATEGORIZERS[filterName];
  if (!categorize) return null;

  const counts = {};
  // Виплата — єдина група, де картка буває в кількох опціях одразу: у
  // агенції дві програми на різні суми. Тож і число додається кожній.
  if (filterName === 'payment') {
    (Array.isArray(users) ? users : []).forEach(user => {
      listPaymentBuckets(user, programRates).forEach(bucket => { counts[bucket] = (counts[bucket] || 0) + 1; });
    });
    return counts;
  }
  (Array.isArray(users) ? users : []).forEach(user => {
    if (filterName === 'userRole') {
      toRoleCategories(user, roleIndexSets).forEach(key => { counts[key] = (counts[key] || 0) + 1; });
      return;
    }
    const bucket = filterName === 'userRole' ? categorize(user, roleIndexSets) : categorize(user);
    const key = bucket === undefined || bucket === null || bucket === '' ? 'other' : String(bucket);
    counts[key] = (counts[key] || 0) + 1;
  });
  return counts;
};

/**
 * Числа групи, яка сама звужує деку: вимкненим опціям — `null`, тобто «числа
 * немає».
 *
 * Сторінки джерела набираються вже відфільтрованими
 * (`collectFilteredMatchingSourceCards`), тож вимкненої опції в деці немає за
 * побудовою, і порахувати її тут неможливо. Нуль біля неї означав «стрічка їх
 * не вантажила», а читався як «таких анкет немає»: СМ бачила «Біологічні
 * батьки 0» під підписом «серед усіх карток стрічки», а ввімкнувши опцію,
 * діставала півтора десятка анкет.
 */
export const withUnloadedFilterOptions = (counts, appliedGroup) => {
  if (!counts || !hasActiveSearchKeyFilterGroup(appliedGroup)) return counts;
  const unloaded = Object.keys(appliedGroup).filter(key => appliedGroup[key] === false);
  return { ...counts, ...Object.fromEntries(unloaded.map(key => [key, null])) };
};

/**
 * Чи правдиве число на «Показати N» — тобто чи нема чого показати поза
 * вже завантаженим.
 *
 * Кнопка рахує по деці в памʼяті, а застосований фільтр дочитує джерело,
 * доки сторінка не набереться (`collectFilteredMatchingSourceCards`). Тож
 * число точне лише тоді, коли стрічку дочитано до кінця **й** чернетка не
 * вмикає того, що застосований фільтр уже відсіяв: відсіяного в деці немає
 * за побудовою. Інакше це нижня межа, і кнопка обіцяла «Показати 2», а
 * застосований фільтр показував пʼятдесят сім анкет.
 */
export const isDraftFilterCountExact = ({ appliedFilters, draftFilters, deckHasMore } = {}) => {
  if (deckHasMore) return false;
  return !Object.entries(draftFilters || {}).some(([groupName, draftGroup]) => {
    const appliedGroup = appliedFilters?.[groupName];
    if (!draftGroup || typeof draftGroup !== 'object' || !appliedGroup || typeof appliedGroup !== 'object') return false;
    return Object.keys(draftGroup).some(key => draftGroup[key] === true && appliedGroup[key] === false);
  });
};
